test_that("AgERA5 process orchestration completes all ncdf4 members and reruns safely", {
  skip_if_not_installed("ncdf4")
  skip_if_not_installed("terra")
  base <- test_external_root("agera5-process"); src <- file.path(base,"members"); raw <- file.path(base,"raw"); dir.create(src,recursive=TRUE); dir.create(raw,recursive=TRUE)
  spec <- get_variable_spec("agera5_relhum_min")
  cfg <- list(project=list(dataset_id=spec$id,profile="smoke"), spatial=list(source_grid_degrees=.1,align_request_to_source_grid=TRUE,api_bbox_buffer_degrees=1,mask_to_template=TRUE,mask_to_boundary=FALSE,require_complete_template_coverage=TRUE), cds=list(dataset_short_name=spec$dataset_short_name,variable=spec$cds_variable,daily_statistic=spec$daily_statistic,dataset_version="2_0"), processing=list(resampling_method="bilinear",datatype="FLT4S",naflag=-9999), validation=list(minimum_celsius=0,maximum_celsius=100,minimum=0,maximum=100,physical_minimum_percent=0,physical_maximum_percent=100,clamp_tolerance_percent=.5,hard_tolerance=1e-6,require_exact_template_geometry=TRUE))
  dates <- as.Date(c("2025-06-01","2025-06-02","2025-06-03")); make_member <- function(d, invalid=FALSE) {ld<-ncdf4::ncdim_def("lon","degrees_east",c(-126,-125.9)); ad<-ncdf4::ncdim_def("lat","degrees_north",c(42.8,42.7)); tm<-ncdf4::ncdim_def("time","days since 1900-01-01 00:00:00",as.numeric(d-as.Date("1900-01-01"))); v<-ncdf4::ncvar_def("Derived_Relative_Humidity_2m_Min_24h","%",list(ld,ad,tm),-9999,prec="double"); p<-file.path(src,paste0("rh_",format(d,"%Y%m%d"),".nc")); n<-ncdf4::nc_create(p,list(v),force_v4=TRUE); ncdf4::ncvar_put(n,v,array(if(invalid)150 else 50,dim=c(2,2,1))); ncdf4::nc_close(n); p }
  members <- vapply(dates,make_member,character(1)); zip_source <- file.path(base,"response.zip"); oldwd<-getwd(); setwd(src); on.exit(setwd(oldwd),add=TRUE); utils::zip(zip_source,basename(members),flags="-q"); setwd(oldwd)
  req <- build_variable_requests(dates,c(42.8,-126,-1.1,-34),cfg,spec)[[1]]; zip_path <- file.path(raw,req$target); file.copy(zip_source,zip_path); req_map <- list(req); preliminary <- data.frame(date=dates,selected_raw_source=zip_path,source_path=zip_path,request_hash=req$request_hash,raw_request_start=min(dates),raw_request_end=max(dates),decoded_source_start=NA,decoded_source_end=NA,mapping_reason="preliminary ZIP source",stringsAsFactors=FALSE)
  template <- terra::rast(nrows=2,ncols=2,xmin=-126.05,xmax=-125.85,ymin=42.65,ymax=42.85,crs="EPSG:4326"); terra::values(template)<-1; template_path<-file.path(base,"template.tif"); terra::writeRaster(template,template_path,overwrite=TRUE)
  run_dir<-file.path(base,"run"); dir.create(run_dir); oldopt<-options(cdsdatagrab.agera5_netcdf_driver_available=FALSE); on.exit(options(oldopt),add=TRUE)
  first <- process_downloaded_variable(zip_path,file.path(base,"daily"),template_path,NA_character_,cfg,spec,expected_dates=dates,run_dir=run_dir,run_expected_dates=dates,request_manifest=req_map,date_source_map=preliminary)
  expect_equal(length(first$written),3); expect_length(first$reused,0); expect_length(first$failed,0); expect_true(file.exists(file.path(run_dir,"agera5_member_diagnostic.json"))); expect_length(first$agera5_diagnostics,3); expect_true(all(vapply(first$agera5_diagnostics,function(x)identical(x$reader_selected,"ncdf4"),logical(1))))
  expect_equal(basename(first$date_source_map$source_path),basename(members)); expect_true(all(grepl("\\.nc$",first$date_source_map$source_path))); expect_equal(nrow(first$date_source_map),3); expect_true(all(first$date_source_map$reader_selected=="ncdf4")); expect_true(all(first$date_source_map$selected_source_variable=="Derived_Relative_Humidity_2m_Min_24h"))
  manifest <- utils::read.csv(file.path(base,"extracted",req$request_hash,"archive_manifest.csv"),stringsAsFactors=FALSE); expect_true(all(manifest$processing_candidate)); expect_true(all(manifest$reader_selected=="ncdf4")); expect_true(all(manifest$source_units=="%")); expect_equal(manifest$source_date,format(dates,"%Y-%m-%d"))
  inv <- inventory_daily_products(file.path(base,"daily"),spec$daily_filename_prefix,template_path,TRUE,cfg); expect_true(all(inv$observed_valid)); final <- final_validate_smoke_run(inv,dates,list(written=character(),reused=character(),incomplete_weeks=data.frame()),template_path); expect_equal(final$status,"success"); expect_equal(sort(basename(inv$path)),paste0("relhum_min_",format(dates,"%Y-%m-%d"),".tif"))
  reused <- process_downloaded_variable(zip_path,file.path(base,"daily"),template_path,NA_character_,cfg,spec,expected_dates=dates,run_dir=run_dir,run_expected_dates=dates,request_manifest=req_map,date_source_map=preliminary); expect_length(reused$written,0); expect_equal(length(reused$reused),3); expect_length(reused$failed,0); expect_true(isTRUE(attr(extract_agera5_archive(zip_path,file.path(raw,"..","extracted"),req$request_hash,spec),"extraction_reused"))); expect_true(file.exists(file.path(run_dir,"agera5_member_diagnostic.json")))
})

test_that("AgERA5 process preserves the original invalid-member error", {
  skip_if_not_installed("ncdf4"); skip_if_not_installed("terra")
  base <- test_external_root("agera5-process-invalid"); src <- file.path(base,"members"); raw <- file.path(base,"raw"); dir.create(src,recursive=TRUE); dir.create(raw,recursive=TRUE); spec<-get_variable_spec("agera5_relhum_min"); dates<-as.Date(c("2025-06-01","2025-06-02","2025-06-03"))
  make <- function(d,bad=FALSE){ld<-ncdf4::ncdim_def("lon","degrees_east",c(-126,-125.9));ad<-ncdf4::ncdim_def("lat","degrees_north",c(42.8,42.7));tm<-ncdf4::ncdim_def("time","days since 1900-01-01 00:00:00",as.numeric(d-as.Date("1900-01-01")));v<-ncdf4::ncvar_def("Derived_Relative_Humidity_2m_Min_24h","%",list(ld,ad,tm),-9999,prec="double");p<-file.path(src,paste0("rh_",format(d,"%Y%m%d"),".nc"));n<-ncdf4::nc_create(p,list(v),force_v4=TRUE);ncdf4::ncvar_put(n,v,array(if(bad)150 else 50,dim=c(2,2,1)));ncdf4::nc_close(n);p}; files<-c(make(dates[[1]]),make(dates[[2]],TRUE),make(dates[[3]])); z<-file.path(base,"bad.zip");ow<-getwd();setwd(src);on.exit(setwd(ow),add=TRUE);utils::zip(z,basename(files),flags="-q");setwd(ow)
  cfg<-list(project=list(dataset_id=spec$id,profile="smoke"),spatial=list(source_grid_degrees=.1,align_request_to_source_grid=TRUE,mask_to_template=TRUE,mask_to_boundary=FALSE,require_complete_template_coverage=TRUE),processing=list(resampling_method="bilinear",datatype="FLT4S",naflag=-9999),validation=list(minimum_celsius=0,maximum_celsius=100,minimum=0,maximum=100,physical_minimum_percent=0,physical_maximum_percent=100,clamp_tolerance_percent=.5,hard_tolerance=1e-6,require_exact_template_geometry=TRUE));template<-terra::rast(nrows=2,ncols=2,xmin=-126.05,xmax=-125.85,ymin=42.65,ymax=42.85,crs="EPSG:4326");terra::values(template)<-1;tp<-file.path(base,"template.tif");terra::writeRaster(template,tp,overwrite=TRUE);req<-list(list(target="agera5_relhum_min_daily_2025-06-01-bad.zip",request_hash="badrequest",year="2025",month="06",day=c("01","02","03"),adapter="agera5",variable_spec_hash=spec$variable_spec_hash));badpath<-file.path(raw,req[[1]]$target);file.copy(z,badpath);map<-data.frame(date=dates,selected_raw_source=badpath,source_path=badpath,request_hash="badrequest",raw_request_start=min(dates),raw_request_end=max(dates),decoded_source_start=NA,decoded_source_end=NA,mapping_reason="preliminary ZIP source",stringsAsFactors=FALSE);rd<-file.path(base,"run");dir.create(rd);oldopt<-options(cdsdatagrab.agera5_netcdf_driver_available=FALSE);on.exit(options(oldopt),add=TRUE);out<-process_downloaded_variable(badpath,file.path(base,"daily"),tp,NA_character_,cfg,spec,expected_dates=dates,run_dir=rd,run_expected_dates=dates,request_manifest=req,date_source_map=map);expect_length(out$failed,1);expect_true(grepl("materially invalid|relative-humidity",paste(vapply(out$processing_failures,`[[`,character(1),"error_message"),collapse=" "),ignore.case=TRUE));expect_length(out$agera5_diagnostics,3);expect_true(file.exists(file.path(rd,"agera5_member_diagnostic.json")))
})
